class LFUCache {
    private int capacity;
    private int minFreq;
    private java.util.HashMap<Integer, int[]> keyMap;
    private java.util.HashMap<Integer, java.util.LinkedHashSet<Integer>> freqMap;

    public LFUCache(int capacity) {
        this.capacity = capacity;
        this.minFreq = 0;
        keyMap = new java.util.HashMap<>();
        freqMap = new java.util.HashMap<>();
    }

    public int get(int key) {
        if (!keyMap.containsKey(key)) return -1;
        int[] info = keyMap.get(key);
        int val = info[0], freq = info[1];
        freqMap.get(freq).remove(key);
        if (freqMap.get(freq).isEmpty()) {
            freqMap.remove(freq);
            if (minFreq == freq) minFreq++;
        }
        info[1] = freq + 1;
        freqMap.computeIfAbsent(freq + 1, k -> new java.util.LinkedHashSet<>()).add(key);
        return val;
    }

    public void put(int key, int value) {
        if (capacity <= 0) return;
        if (keyMap.containsKey(key)) {
            keyMap.get(key)[0] = value;
            get(key);
            return;
        }
        if (keyMap.size() >= capacity) {
            java.util.LinkedHashSet<Integer> minSet = freqMap.get(minFreq);
            int evict = minSet.iterator().next();
            minSet.remove(evict);
            if (minSet.isEmpty()) freqMap.remove(minFreq);
            keyMap.remove(evict);
        }
        keyMap.put(key, new int[]{value, 1});
        freqMap.computeIfAbsent(1, k -> new java.util.LinkedHashSet<>()).add(key);
        minFreq = 1;
    }
}

import java.util.*;

class LFUCache {
    private int capacity, minFreq;
    private Map<Integer, int[]> keyInfo;
    private Map<Integer, LinkedHashMap<Integer, Integer>> freqBuckets;

    public LFUCache(int capacity) {
        this.capacity = capacity;
        this.minFreq = 0;
        keyInfo = new HashMap();
        freqBuckets = new HashMap();
    }

    private void increaseFreq(int key) {
        int[] info = keyInfo.get(key);
        int freq = info[1];
        LinkedHashMap<Integer, Integer> bucket = freqBuckets.get(freq);
        bucket.remove(key);
        if (bucket.isEmpty()) {
            freqBuckets.remove(freq);
            if (minFreq == freq) minFreq++;
        }
        info[1] = freq + 1;
        if (!freqBuckets.containsKey(freq + 1)) {
            freqBuckets.put(freq + 1, new LinkedHashMap());
        }
        freqBuckets.get(freq + 1).put(key, info[0]);
    }

    public int get(int key) {
        if (!keyInfo.containsKey(key)) return -1;
        increaseFreq(key);
        return keyInfo.get(key)[0];
    }

    public void put(int key, int value) {
        if (capacity <= 0) return;
        if (keyInfo.containsKey(key)) {
            keyInfo.get(key)[0] = value;
            increaseFreq(key);
            return;
        }
        if (keyInfo.size() >= capacity) {
            LinkedHashMap<Integer, Integer> minBucket = freqBuckets.get(minFreq);
            int evictKey = minBucket.keySet().iterator().next();
            minBucket.remove(evictKey);
            if (minBucket.isEmpty()) freqBuckets.remove(minFreq);
            keyInfo.remove(evictKey);
        }
        keyInfo.put(key, new int[]{value, 1});
        if (!freqBuckets.containsKey(1)) {
            freqBuckets.put(1, new LinkedHashMap());
        }
        freqBuckets.get(1).put(key, value);
        minFreq = 1;
    }
}
